// idiomatic: ownership replaces the read set / write set
actor Ledger {
    private var balances: [String: Int] = [:]
    func transfer(from: String, to: String, amount: Int) async throws {
        guard (balances[from] ?? 0) >= amount else { throw LedgerError.insufficient }
        balances[from]! -= amount            // no other actor sees an intermediate state
        balances[to, default: 0] += amount
        // NOTE: any await below re-introduces interleaving; re-validate after one.
    }
}

